# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def kthLargestLevelSum(self, root: Optional[TreeNode], k: int) -> int:
        heap = []
        queue = collections.deque([root])

        while queue:
            n = len(queue)
            levelSum = 0
            for _ in range(n):
                node = queue.popleft()
                if node:
                    levelSum += node.val
                    queue.append(node.left)
                    queue.append(node.right)
            if levelSum:
                heapq.heappush(heap, levelSum)

            if len(heap) > k:
                heapq.heappop(heap)

        if len(heap) < k:
            return -1

        return heap[-k]
